const fs = require('fs');

const data = fs.readFileSync(0);
let pos = 0;
const len = data.length;

function nextInt() {
  while (pos < len && data[pos] <= 32) pos++;
  let num = 0;
  while (pos < len && data[pos] > 32) {
    num = num * 10 + (data[pos] - 48);
    pos++;
  }
  return num;
}

const N = nextInt();
const B = nextInt();

const U = new Int32Array(B);
const V = new Int32Array(B);
const P = new Int32Array(B);

for (let i = 0; i < B; i++) {
  U[i] = nextInt();
  V[i] = nextInt();
  P[i] = nextInt();
}

const C = nextInt();

const order = new Int32Array(B);
for (let i = 0; i < B; i++) order[i] = i;
order.sort((a, b) => P[b] - P[a]);

const MAX = 2 * N + 5;
const LOG = Math.ceil(Math.log2(MAX)) + 1;

const parent = new Int32Array(MAX);
const weight = new Int32Array(MAX);
const depth = new Int32Array(MAX);

const up = new Array(LOG);
for (let j = 0; j < LOG; j++) {
  up[j] = new Int32Array(MAX);
}

const dsu = new Int32Array(N + 1);
const sz = new Int32Array(N + 1);
const compRoot = new Int32Array(N + 1);

for (let i = 1; i <= N; i++) {
  dsu[i] = i;
  sz[i] = 1;
  compRoot[i] = i;
}

function find(x) {
  while (dsu[x] !== x) {
    dsu[x] = dsu[dsu[x]];
    x = dsu[x];
  }
  return x;
}

let nextNode = N + 1;

for (let oi = 0; oi < B; oi++) {
  const i = order[oi];
  const u = U[i];
  const v = V[i];
  const p = P[i];

  let ru = find(u);
  let rv = find(v);

  if (ru === rv) continue;

  const rootU = compRoot[ru];
  const rootV = compRoot[rv];

  const newNode = nextNode++;
  weight[newNode] = p;
  parent[rootU] = newNode;
  parent[rootV] = newNode;

  if (sz[ru] < sz[rv]) {
    const tmp = ru;
    ru = rv;
    rv = tmp;
  }

  dsu[rv] = ru;
  sz[ru] += sz[rv];
  compRoot[ru] = newNode;
}

const root = compRoot[find(1)];
parent[root] = 0;

for (let i = root; i >= 1; i--) {
  const p = parent[i];

  if (p !== 0) {
    depth[i] = depth[p] + 1;
    up[0][i] = p;
  } else {
    depth[i] = 0;
    up[0][i] = 0;
  }

  for (let j = 1; j < LOG; j++) {
    const mid = up[j - 1][i];
    up[j][i] = mid !== 0 ? up[j - 1][mid] : 0;
  }
}

function lca(u, v) {
  if (depth[u] < depth[v]) {
    const tmp = u;
    u = v;
    v = tmp;
  }

  let diff = depth[u] - depth[v];

  for (let j = 0; j < LOG; j++) {
    if (diff & (1 << j)) {
      u = up[j][u];
    }
  }

  if (u === v) return u;

  for (let j = LOG - 1; j >= 0; j--) {
    const uu = up[j][u];
    const vv = up[j][v];

    if (uu !== vv) {
      u = uu;
      v = vv;
    }
  }

  return parent[u];
}

const out = new Array(C);

for (let q = 0; q < C; q++) {
  const x = nextInt();
  const y = nextInt();
  out[q] = weight[lca(x, y)];
}

process.stdout.write(out.join('\n') + '\n');
